          input.disabled = item.dependsOn ? (s[item.dependsOn] !== true) : false;
          var label = panel.querySelector('[data-ces-val="' + item.key + '"]');
          if (label) label.textContent = input.disabled ? "已关闭" : (shown + (item.unit || ""));
